// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(t < block.timestamp); // a past time: admissible input to Put
        uint256 amount = 2 ether;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);

        // Immediate withdrawal attempt: P refuses (unlockTime clamped to now), M allows it.
        vm.prank(actor);
        c.Collect(amount);

        (uint256 unlockTime, uint256 bal) = c.Acc(actor);
        unlockTime; // silence unused
        assertTrue(bal == amount, "balance must be unchanged immediately after Put");
    }
}
